pragma solidity ^0.8.20;

// OpenZeppelin v4.9.x imports
import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

// --- Uniswap v4 Interfaces & Libraries ---

struct PoolKey {
    address currency0;
    address currency1;
    uint24 fee;
    int24 tickSpacing;
    address hooks;
}

library PoolId {
    function compute(PoolKey memory key) internal pure returns (bytes32) {
        return keccak256(abi.encode(key));
    }
}

interface IPoolManager {
    struct SwapParams {
        bool zeroForOne;
        int256 amountSpecified;
        uint160 sqrtPriceLimitX96;
    }
    function lock(bytes calldata data) external returns (bytes memory);
}

interface IHooks {
    function beforeSwap(
        address sender,
        PoolKey calldata key,
        IPoolManager.SwapParams calldata params,
        bytes calldata data
    ) external returns (bytes4);

    function afterSwap(
        address sender,
        PoolKey calldata key,
        IPoolManager.SwapParams calldata params,
        bytes calldata data
    ) external returns (bytes4);

    function lockAcquired(bytes calldata data) external returns (bytes memory);
}

library Hooks {
    uint160 public constant BEFORE_SWAP_FLAG = 1 << 9;
    uint160 public constant AFTER_SWAP_FLAG = 1 << 10;
}

// --- Application-specific Interfaces and Contracts ---

interface IINRT {
    function requestWithdrawalFromHook(
        bytes32 requestId,
        address user,
        uint256 amount,
        string calldata upiId
    ) external;
}

/**
 * @title Indian Rupee Token (INRT)
 * @author Solidity Expert
 * @notice An ERC20 token backed 1:1 by Indian Rupees in a bank.
 * @dev This contract manages minting against bank deposits, burning for withdrawals,
 * and pausing transfers. It interacts with a CryptoUPIHook for withdrawal requests.
 */
contract INRT is ERC20, Ownable, Pausable {
    struct Withdrawal {
        address user;
        uint256 amount;
        string upiId;
        uint256 timestamp;
        bool processed;
    }

    uint256 public totalBankReserves;
    address public hookContract;

    mapping(string => bool) public processedBankTxIds;
    mapping(bytes32 => Withdrawal) public withdrawals;

    event TokensMinted(address indexed to, uint256 amount, string bankTxId);
    event TokensBurned(address indexed from, uint256 amount, bytes32 indexed withdrawalRequestId);
    event WithdrawalRequested(bytes32 indexed requestId, address indexed user, uint256 amount, string upiId);
    event WithdrawalProcessed(bytes32 indexed requestId);
    event HookContractUpdated(address indexed newHookAddress, bool isAuthorized);

    constructor() ERC20("Indian Rupee Token", "INRT") {
        // Hard-coded name and symbol. Decimals are overridden below.
    }

    /**
     * @inheritdoc ERC20
     */
    function decimals() public pure override returns (uint8) {
        return 18;
    }

    /**
     * @notice Mints new INRT tokens against a confirmed bank deposit.
     * @dev The bankTxId must be unique to prevent double-minting for the same deposit.
     * @param to The address to receive the minted tokens.
     * @param amount The amount of tokens to mint (should equal the INR deposit).
     * @param bankTxId A unique identifier for the bank transaction.
     */
    function mint(address to, uint256 amount, string calldata bankTxId) external onlyOwner {
        require(bytes(bankTxId).length > 0, "INRT: Bank transaction ID cannot be empty");
        require(!processedBankTxIds[bankTxId], "INRT: Bank transaction ID already processed");

        processedBankTxIds[bankTxId] = true;
        totalBankReserves += amount;
        _mint(to, amount);

        emit TokensMinted(to, amount, bankTxId);
    }

    /**
     * @notice Called by the authorized hook contract to log a withdrawal request.
     * @dev This function does not burn tokens; it stages the withdrawal for processing.
     * @param requestId A unique ID for the withdrawal request.
     * @param user The user who is withdrawing.
     * @param amount The amount of INRT to be withdrawn.
     * @param upiId The user's UPI ID for the bank transfer.
     */
    function requestWithdrawalFromHook(
        bytes32 requestId,
        address user,
        uint256 amount,
        string calldata upiId
    ) external {
        require(msg.sender == hookContract, "INRT: Caller is not the authorized hook");
        require(withdrawals[requestId].user == address(0), "INRT: Withdrawal request ID already exists");

        withdrawals[requestId] = Withdrawal({
            user: user,
            amount: amount,
            upiId: upiId,
            timestamp: block.timestamp,
            processed: false
        });

        emit WithdrawalRequested(requestId, user, amount, upiId);
    }

    /**
     * @notice Marks a withdrawal as processed and burns the corresponding tokens.
     * @dev This is called by the owner after the off-chain INR transfer is complete.
     * @param requestId The ID of the withdrawal request to process.
     */
    function burnForWithdrawal(bytes32 requestId) external onlyOwner {
        Withdrawal storage w = withdrawals[requestId];
        require(w.user != address(0), "INRT: Withdrawal does not exist");
        require(!w.processed, "INRT: Withdrawal already processed");
        require(totalBankReserves >= w.amount, "INRT: Burn amount exceeds total reserves");

        w.processed = true;
        totalBankReserves -= w.amount;
        _burn(w.user, w.amount);

        emit TokensBurned(w.user, w.amount, requestId);
        emit WithdrawalProcessed(requestId);
    }

    /**
     * @notice Pauses all token transfers.
     */
    function pause() external onlyOwner {
        _pause();
    }

    /**
     * @notice Unpauses token transfers.
     */
    function unpause() external onlyOwner {
        _unpause();
    }

    /**
     * @notice Authorizes or revokes a contract to act as the withdrawal hook.
     * @param _hookAddress The address of the hook contract.
     * @param authorized True to authorize, false to revoke.
     */
    function setHookContract(address _hookAddress, bool authorized) external onlyOwner {
        hookContract = authorized ? _hookAddress : address(0);
        emit HookContractUpdated(_hookAddress, authorized);
    }

    function _beforeTokenTransfer(address from, address to, uint256 amount) internal virtual override {
        super._beforeTokenTransfer(from, to, amount);
        require(!paused(), "INRT: token transfer while paused");
    }

    // --- View Functions ---

    function getWithdrawalDetails(bytes32 requestId)
        external
        view
        returns (address user, uint256 amount, string memory upiId, uint256 timestamp, bool processed)
    {
        Withdrawal storage w = withdrawals[requestId];
        return (w.user, w.amount, w.upiId, w.timestamp, w.processed);
    }

    function isBankTxIdProcessed(string calldata bankTxId) external view returns (bool) {
        return processedBankTxIds[bankTxId];
    }

    function getBackingRatio() external view returns (uint256) {
        uint256 currentSupply = totalSupply();
        if (currentSupply == 0) {
            return 1e18; // 1:1 ratio
        }
        return (totalBankReserves * 1e18) / currentSupply;
    }
}


/**
 * @title CryptoUPIHook
 * @author Solidity Expert
 * @notice A Uniswap v4 hook to facilitate INRT withdrawals to UPI.
 * @dev This hook uses the beforeSwap/afterSwap/lockAcquired pattern to reliably
 * determine the amount of INRT received by a user in a swap.
 */
contract CryptoUPIHook is IHooks, Ownable {
    IINRT public inrtToken;
    address public usdtToken;
    bytes32 public poolId;
    IPoolManager public poolManager;

    mapping(bytes32 => bool) public processedRequests;
    mapping(address => uint256) private swapInitialInrtBalance;

    constructor() {
        // Empty constructor per requirements
    }

    function setPool(address _poolManager, PoolKey calldata key, address _inrtToken) external onlyOwner {
        require(address(inrtToken) == address(0), "Hook: Already initialized");
        require(_poolManager != address(0) && _inrtToken != address(0), "Hook: Zero address");
        require(key.hooks == address(this), "Hook: Hook address mismatch in key");
        require(key.currency0 == _inrtToken || key.currency1 == _inrtToken, "Hook: INRT not in pool");

        poolManager = IPoolManager(_poolManager);
        inrtToken = IINRT(_inrtToken);

        if (key.currency0 == _inrtToken) {
            usdtToken = key.currency1;
        } else {
            usdtToken = key.currency0;
        }
        poolId = PoolId.compute(key);
    }

    function getHookCalls() external pure returns (uint160) {
        return Hooks.BEFORE_SWAP_FLAG | Hooks.AFTER_SWAP_FLAG;
    }

    function beforeSwap(
        address sender,
        PoolKey calldata key,
        IPoolManager.SwapParams calldata params,
        bytes calldata data
    ) external override returns (bytes4) {
        require(msg.sender == address(poolManager), "Hook: Must be called by PoolManager");
        // If data is provided, it's a potential withdrawal swap.
        // Record the user's INRT balance before the swap.
        if (data.length > 0) {
            address tokenOut = params.zeroForOne ? key.currency0 : key.currency1;
            // Only record balance if the swap is for INRT
            if (tokenOut == address(inrtToken)) {
                swapInitialInrtBalance[sender] = IERC20(address(inrtToken)).balanceOf(sender);
            }
        }
        return this.beforeSwap.selector;
    }

    function afterSwap(
        address sender,
        PoolKey calldata key,
        IPoolManager.SwapParams calldata params,
        bytes calldata data
    ) external override returns (bytes4) {
        require(msg.sender == address(poolManager), "Hook: Must be called by PoolManager");
        // If an initial balance was stored, it means this was a withdrawal swap.
        // Request a lock to securely read the final balance.
        if (swapInitialInrtBalance[sender] > 0 || data.length > 0) {
            address tokenOut = params.zeroForOne ? key.currency0 : key.currency1;
            if (tokenOut == address(inrtToken)) {
                // Pass sender address and original hook data to lockAcquired
                poolManager.lock(abi.encode(sender, data));
            }
        }
        return this.afterSwap.selector;
    }

    function lockAcquired(bytes calldata data) external override returns (bytes memory) {
        require(msg.sender == address(poolManager), "Hook: Must be called by PoolManager");

        (address sender, bytes memory hookData) = abi.decode(data, (address, bytes));

        uint256 initialBalance = swapInitialInrtBalance[sender];
        delete swapInitialInrtBalance[sender]; // Clean up state

        // Ensure we don't process if something went wrong in beforeSwap
        // or if hookData is empty after all.
        if (hookData.length == 0) return ""; 

        uint256 finalBalance = IERC20(address(inrtToken)).balanceOf(sender);

        if (finalBalance > initialBalance) {
            uint256 inrtReceived = finalBalance - initialBalance;
            (bytes32 requestId, string memory upiId) = abi.decode(hookData, (bytes32, string));

            if (!processedRequests[requestId]) {
                processedRequests[requestId] = true;
                inrtToken.requestWithdrawalFromHook(requestId, sender, inrtReceived, upiId);
            }
        }
        return ""; // No return data needed
    }

    function encodeHookData(bytes32 requestId, string calldata upiId) external pure returns (bytes memory) {
        return abi.encode(requestId, upiId);
    }

    // --- View Functions ---

    function getPoolDetails() external view returns (bool isInitialized, address configuredUsdtToken, bytes32 configuredPoolId) {
        isInitialized = address(poolManager) != address(0);
        configuredUsdtToken = usdtToken;
        configuredPoolId = poolId;
    }
}

